"""
3 nieuwe secties toegevoegd aan Portfolio Watch, zodat de mail ook in een
rustige week (geen trend-flips/earnings) nog waardevolle inhoud heeft:

1. WEKELIJKS PORTFOLIO-RENDEMENT: gewogen op huidige positiewaarde
   (shares x prijs), zodat een grote positie logischerwijs zwaarder
   meetelt dan een kleine -- niet een simpel gemiddelde.
2. BESTE/SLECHTSTE POSITIE DEZE WEEK: valt automatisch weg als er maar
   1 positie bekend is (zou anders 2x dezelfde tonen).
3. AANKOMENDE EARNINGS VOLGENDE WEEK: vooruitkijkend (i.p.v. de
   al-gerapporteerde-cijfers-check) -- nieuwe functie
   get_upcoming_earnings_date(), checkt yfinance's earnings-kalender op
   cijfers binnen de komende 7 dagen.

check_holding() geeft nu ook week_change_pct en upcoming_earnings_date
terug (in alle 3 mogelijke return-paden). get_current_holdings() en de
main()-loop (portfolio_watch.py) + run_portfolio_emails()
(weekly_batch.py) geven nu ook 'shares' door, nodig voor de gewogen
berekening.

Gebruik: python fix_portfolio_watch_weekly_return_and_earnings.py
Draai dit vanuit je stock_screener-map (hestys-fresh).
"""

PORTFOLIO_WATCH_CONTENT = b'"""\r\nPortfolio Watch: volgt de HUIDIGE Supertrend-status van je eigen bestaande\r\nposities (in tegenstelling tot screener.py, dat naar NIEUWE idee\xc3\xabn in\r\nAEX/Nasdaq-100 zoekt). Dit is vooral relevant bij een geconcentreerde\r\nportfolio -- weten of je grootste positie (bv. Tesla) nog steeds in een\r\nbullish trend zit, is vaak belangrijker dan een willekeurig nieuw signaal.\r\n\r\nHaalt je posities nu RECHTSTREEKS uit de database (dezelfde die \'My\r\nPortfolio\' op de site gebruikt), i.p.v. een hardgecodeerde lijst die\r\nhandmatig bijgewerkt moest worden -- deze mail blijft nu altijd\r\ngesynchroniseerd met wat je daadwerkelijk bezit, ook als je iets koopt\r\nof verkoopt. Alleen posities met shares > 0 worden meegenomen (geen\r\nwatchlist-items, geen posities die je al verkocht hebt).\r\n\r\nVereist: pip install -r requirements.txt\r\nVereist env-var: PORTFOLIO_WATCH_USER_EMAIL (welk account de posities gevolgd worden)\r\n\r\nGebruik: python portfolio_watch.py\r\n"""\r\nfrom __future__ import annotations\r\n\r\nimport os\r\n\r\nimport pandas as pd\r\nimport yfinance as yf\r\n\r\nfrom indicators import supertrend, ema, resample_to_weekly\r\nfrom screener import get_roic_data, fetch_weekly, get_earnings_surprise\r\nfrom emailer import send_email, is_configured as email_is_configured\r\nfrom database import get_user_holdings\r\n\r\n\r\ndef get_current_holdings() -> list:\r\n    """\r\n    Haalt de ACTUELE, eigen posities op uit de database (i.p.v. een\r\n    hardgecodeerde lijst) -- alleen posities met shares > 0 (geen\r\n    watchlist-items, geen verkochte posities). Vereist de env-var\r\n    PORTFOLIO_WATCH_USER_EMAIL, zodat dit script weet WELK account\r\n    gevolgd moet worden (het draait immers los van een ingelogde sessie).\r\n    """\r\n    user_email = os.getenv("PORTFOLIO_WATCH_USER_EMAIL")\r\n    if not user_email:\r\n        raise ValueError(\r\n            "PORTFOLIO_WATCH_USER_EMAIL is niet ingesteld -- Portfolio Watch weet "\r\n            "hierdoor niet welk account de posities gevolgd moeten worden."\r\n        )\r\n    all_holdings = get_user_holdings(user_email, is_watchlist=False)\r\n    return [\r\n        {"naam": h["naam"], "ticker": h["ticker"], "shares": h["shares"]}\r\n        for h in all_holdings\r\n        if (h.get("shares") or 0) > 0\r\n    ]\r\n\r\nATR_LENGTH = 6\r\nATR_MULTIPLIER = 2.6\r\nTREND_FILTER_EMA_LENGTH = 20\r\nRECENT_CHANGE_WEEKS = 2  # een statusverandering binnen dit aantal weken wordt als \'LET OP\' gemarkeerd\r\nEARNINGS_RECENT_DAYS = 7  # hoe recent gerapporteerde cijfers moeten zijn om als \'deze week\' te tellen\r\n\r\n\r\ndef get_upcoming_earnings_date(ticker: str):\n    """\n    Checkt of deze positie AANKOMENDE cijfers heeft binnen de komende 7\n    dagen -- vooruitkijkend, in tegenstelling tot get_earnings_surprise()\n    (die kijkt naar AL gerapporteerde cijfers). Geeft None terug als er\n    geen aankomende cijfers binnen dat venster zijn, of als het niet op\n    te halen is.\n    """\n    try:\n        earnings_dates = yf.Ticker(ticker).get_earnings_dates(limit=8)\n        if earnings_dates is None or earnings_dates.empty:\n            return None\n        today = pd.Timestamp.now(tz=earnings_dates.index.tz).normalize()\n        window_end = today + pd.Timedelta(days=7)\n        future_dates = earnings_dates.index[(earnings_dates.index >= today) & (earnings_dates.index <= window_end)]\n        return future_dates[0] if len(future_dates) > 0 else None\n    except Exception:\n        return None\n\n\ndef check_holding(naam: str, ticker: str):\r\n    # Earnings-verrassing (al gerapporteerd) EN aankomende earnings (komende\r\n    # 7 dagen) zijn allebei onafhankelijk van of er genoeg historie is voor\r\n    # Supertrend -- altijd proberen op te halen, ook als de technische check\r\n    # hieronder faalt.\r\n    earnings_info = get_earnings_surprise(ticker)\r\n    upcoming_earnings = get_upcoming_earnings_date(ticker)\r\n\r\n    try:\r\n        df = fetch_weekly(ticker)\r\n    except Exception as exc:\r\n        print(f"  {naam} ({ticker}): fout bij ophalen ({exc})")\r\n        return {\r\n            "naam": naam, "ticker": ticker, "status": "ONBEKEND (fout bij ophalen)",\r\n            "sinds": None, "weken_in_trend": None, "recent_gewijzigd": False,\r\n            "prijs": None, "boven_ema20": None, "roic_pct": None, "roic_trend": "onbekend",\r\n            "week_change_pct": None,\r\n            "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n            "earnings_beat": earnings_info["beat"],\r\n            "earnings_date": earnings_info["earnings_date"],\r\n            "upcoming_earnings_date": upcoming_earnings,\r\n        }\r\n\r\n    min_needed = max(ATR_LENGTH, TREND_FILTER_EMA_LENGTH) + 5\r\n    if df.empty or len(df) < min_needed:\r\n        print(f"  {naam} ({ticker}): te weinig data voor Supertrend (nodig: {min_needed}, "\r\n              f"gekregen: {len(df)})")\r\n        latest_price = round(float(df[\'close\'].iloc[-1]), 2) if not df.empty else None\r\n        week_change_pct = None\r\n        if len(df) >= 2:\r\n            prev_close = float(df["close"].iloc[-2])\r\n            if prev_close:\r\n                week_change_pct = (float(df["close"].iloc[-1]) - prev_close) / prev_close * 100\r\n        return {\r\n            "naam": naam, "ticker": ticker, "status": "ONBEKEND (te weinig historie)",\r\n            "sinds": None, "weken_in_trend": None, "recent_gewijzigd": False,\r\n            "prijs": latest_price, "boven_ema20": None, "roic_pct": None, "roic_trend": "onbekend",\r\n            "week_change_pct": week_change_pct,\r\n            "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n            "earnings_beat": earnings_info["beat"],\r\n            "earnings_date": earnings_info["earnings_date"],\r\n            "upcoming_earnings_date": upcoming_earnings,\r\n        }\r\n\r\n    st = supertrend(df, length=ATR_LENGTH, multiplier=ATR_MULTIPLIER)\r\n    df = df.copy()\r\n    df["trend_dir"] = st["trend_dir"]\r\n    df["ema_trend"] = ema(df["close"], TREND_FILTER_EMA_LENGTH)\r\n\r\n    current_trend = int(df["trend_dir"].iloc[-1])\r\n    trend_changes = df.index[df["trend_dir"] != df["trend_dir"].shift(1)]\r\n    last_change = trend_changes[-1] if len(trend_changes) > 0 else df.index[0]\r\n    weeks_in_current_trend = len(df.loc[last_change:]) - 1\r\n\r\n    latest_row = df.iloc[-1]\r\n    roic_data = get_roic_data(ticker)\r\n\r\n    prev_close = float(df["close"].iloc[-2])\r\n    week_change_pct = (float(latest_row["close"]) - prev_close) / prev_close * 100 if prev_close else None\r\n\r\n    return {\r\n        "naam": naam,\r\n        "ticker": ticker,\r\n        "status": "BULLISH" if current_trend == 1 else "BEARISH",\r\n        "sinds": last_change.date(),\r\n        "weken_in_trend": weeks_in_current_trend,\r\n        "recent_gewijzigd": weeks_in_current_trend <= RECENT_CHANGE_WEEKS,\r\n        "prijs": round(float(latest_row["close"]), 2),\r\n        "boven_ema20": bool(latest_row["close"] > latest_row["ema_trend"]),\r\n        "roic_pct": round(roic_data["roic"] * 100, 1) if roic_data["roic"] is not None else None,\r\n        "roic_trend": roic_data["roic_trend"],\r\n        "week_change_pct": week_change_pct,\r\n        "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n        "earnings_beat": earnings_info["beat"],\r\n        "earnings_date": earnings_info["earnings_date"],\r\n        "upcoming_earnings_date": upcoming_earnings,\r\n    }\r\n\r\n\r\ndef build_email_body(df: pd.DataFrame) -> tuple:\r\n    """Bouwt de Portfolio Watch-mail -- zelfde Hesty\'s-stijl als de dagelijkse/wekelijkse signalen-mails."""\r\n    changed = df[df["recent_gewijzigd"]]\r\n\r\n    # --- Beknopt: alleen wat DEZE WEEK daadwerkelijk is veranderd, i.p.v.\r\n    # een volledige, elke-keer-herhalende samenvatting van alles. ---\r\n    from datetime import datetime as _datetime\r\n\r\n    def _is_recent_earnings(earnings_date):\r\n        if earnings_date is None:\r\n            return False\r\n        try:\r\n            ed = earnings_date.date() if hasattr(earnings_date, "date") else earnings_date\r\n            days_since = (_datetime.now().date() - ed).days\r\n            return 0 <= days_since <= EARNINGS_RECENT_DAYS\r\n        except Exception:\r\n            return False\r\n\r\n    earnings_mask = df["earnings_date"].apply(_is_recent_earnings) & df["earnings_surprise_pct"].notna()\r\n    earnings_this_week = df[earnings_mask]\r\n\r\n    upcoming_earnings = df[df["upcoming_earnings_date"].notna()].sort_values("upcoming_earnings_date")\r\n\r\n    notable_tickers = set(changed["ticker"]) | set(earnings_this_week["ticker"])\r\n    quiet_positions = df[~df["ticker"].isin(notable_tickers)]\r\n\r\n    # --- Gewogen weekrendement + beste/slechtste positie deze week --\r\n    # gewogen op huidige positiewaarde (shares x prijs), zodat een grote\r\n    # positie logischerwijs zwaarder meetelt dan een kleine.\r\n    df_with_value = df.copy()\r\n    df_with_value["value"] = df_with_value["shares"].fillna(0) * df_with_value["prijs"].fillna(0)\r\n    valid_week = df_with_value[df_with_value["week_change_pct"].notna() & (df_with_value["value"] > 0)]\r\n    portfolio_week_change_pct = None\r\n    if not valid_week.empty and valid_week["value"].sum() > 0:\r\n        portfolio_week_change_pct = (valid_week["week_change_pct"] * valid_week["value"]).sum() / valid_week["value"].sum()\r\n\r\n    best_this_week = worst_this_week = None\r\n    valid_week_moves = df[df["week_change_pct"].notna()]\r\n    if not valid_week_moves.empty:\r\n        best_this_week = valid_week_moves.loc[valid_week_moves["week_change_pct"].idxmax()]\r\n        worst_this_week = valid_week_moves.loc[valid_week_moves["week_change_pct"].idxmin()]\r\n        if best_this_week["ticker"] == worst_this_week["ticker"]:\r\n            worst_this_week = None  # slechts 1 positie met bekende weekbeweging -- niet 2x dezelfde tonen\r\n\r\n    # --- Tekst-versie ---\r\n    text_lines = ["Good morning from Hesty\'s -- here\'s your portfolio watch.", ""]\r\n\r\n    if portfolio_week_change_pct is not None:\r\n        text_lines.append(f"\xf0\x9f\x93\x88 Your portfolio this week: {portfolio_week_change_pct:+.1f}%")\r\n        if best_this_week is not None:\r\n            text_lines.append(f"  Best: {best_this_week[\'naam\']} ({best_this_week[\'ticker\']}) {best_this_week[\'week_change_pct\']:+.1f}%")\r\n        if worst_this_week is not None:\r\n            text_lines.append(f"  Worst: {worst_this_week[\'naam\']} ({worst_this_week[\'ticker\']}) {worst_this_week[\'week_change_pct\']:+.1f}%")\r\n        text_lines.append("")\r\n\r\n    if len(changed) > 0:\r\n        text_lines.append("\xf0\x9f\x94\x84 Trend changes this week:")\r\n        for _, row in changed.iterrows():\r\n            emoji = "\xf0\x9f\x9f\xa2" if row["status"] == "BULLISH" else "\xf0\x9f\x94\xb4"\r\n            text_lines.append(f"  {emoji} {row[\'naam\']} ({row[\'ticker\']}): flipped to {row[\'status\']}")\r\n    else:\r\n        text_lines.append("\xf0\x9f\x94\x84 No trend changes this week.")\r\n    text_lines.append("")\r\n\r\n    if len(earnings_this_week) > 0:\r\n        text_lines.append("\xf0\x9f\x93\x8a Earnings this week:")\r\n        for _, row in earnings_this_week.iterrows():\r\n            beat_txt = "beat" if row["earnings_beat"] else "missed"\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {beat_txt} estimates by {row[\'earnings_surprise_pct\']:+.1f}%")\r\n        text_lines.append("")\r\n\r\n    if len(upcoming_earnings) > 0:\r\n        text_lines.append("\xf0\x9f\x93\x85 Earnings coming up next week:")\r\n        for _, row in upcoming_earnings.iterrows():\r\n            earnings_date_str = row["upcoming_earnings_date"].strftime("%A %Y-%m-%d")\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {earnings_date_str}")\r\n        text_lines.append("")\r\n\r\n    if len(quiet_positions) > 0:\r\n        quiet_names = ", ".join(quiet_positions["ticker"].tolist())\r\n        text_lines.append(f"\xe2\x9c\x85 No notable changes ({len(quiet_positions)} position(s)): {quiet_names}")\r\n        text_lines.append("")\r\n\r\n    text_lines += [\r\n        "See the full picture under Analyze > Portfolio Overview on the site.",\r\n        "",\r\n        "-- Hesty\'s, your personal investment assistant",\r\n        "",\r\n        "This is a screener, not investment advice.",\r\n    ]\r\n    text_body = "\\n".join(text_lines)\r\n\r\n    # --- HTML-versie: zelfde donkere-header-met-jade-accent-stijl als de\r\n    # andere Hesty\'s-mails, maar nu bewust beknopt: korte secties i.p.v.\r\n    # een volledige tabel + nieuws-dump. ---\r\n    week_summary_html = ""\r\n    if portfolio_week_change_pct is not None:\r\n        week_color = "#0F8F6E" if portfolio_week_change_pct >= 0 else "#C1524A"\r\n        best_worst_bits = []\r\n        if best_this_week is not None:\r\n            best_worst_bits.append(\r\n                f"Best: <strong>{best_this_week[\'naam\']} ({best_this_week[\'ticker\']})</strong> "\r\n                f"<span style=\'color:#0F8F6E;\'>{best_this_week[\'week_change_pct\']:+.1f}%</span>"\r\n            )\r\n        if worst_this_week is not None:\r\n            best_worst_bits.append(\r\n                f"Worst: <strong>{worst_this_week[\'naam\']} ({worst_this_week[\'ticker\']})</strong> "\r\n                f"<span style=\'color:#C1524A;\'>{worst_this_week[\'week_change_pct\']:+.1f}%</span>"\r\n            )\r\n        best_worst_html = f"<p style=\'margin:6px 0 0 0; font-size:13px; color:#5B6472;\'>{\' &middot; \'.join(best_worst_bits)}</p>" if best_worst_bits else ""\r\n        week_summary_html = f"""\r\n        <div style="background:#F7F9FA; border-radius:8px; padding:14px 16px; margin-bottom:20px;">\r\n            <span style="font-size:14px; color:#5B6472;">\xf0\x9f\x93\x88 Your portfolio this week</span><br/>\r\n            <span style="font-size:22px; font-weight:700; color:{week_color};">{portfolio_week_change_pct:+.1f}%</span>\r\n            {best_worst_html}\r\n        </div>\r\n        """\r\n\r\n    def _flip_row_html(r):\r\n        emoji = "\xf0\x9f\x9f\xa2" if r["status"] == "BULLISH" else "\xf0\x9f\x94\xb4"\r\n        status_color = "#0F8F6E" if r["status"] == "BULLISH" else "#C1524A"\r\n        return (\r\n            f"<li style=\'padding:6px 0;\'>{emoji} <strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"flipped to <span style=\'color:{status_color}; font-weight:600;\'>{r[\'status\']}</span></li>"\r\n        )\r\n\r\n    if len(changed) > 0:\r\n        flips_html = f"<ul style=\'margin:8px 0; padding-left:20px;\'>{\'\'.join(_flip_row_html(r) for _, r in changed.iterrows())}</ul>"\r\n    else:\r\n        flips_html = "<p style=\'color:#5B6472; margin:8px 0;\'>No trend changes this week.</p>"\r\n\r\n    def _earnings_row_html(r):\r\n        beat_txt = "beat" if r["earnings_beat"] else "missed"\r\n        color = "#0F8F6E" if r["earnings_beat"] else "#C1524A"\r\n        return (\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"{beat_txt} estimates by <span style=\'color:{color}; font-weight:600;\'>{r[\'earnings_surprise_pct\']:+.1f}%</span></li>"\r\n        )\r\n\r\n    earnings_section_html = ""\r\n    if len(earnings_this_week) > 0:\r\n        earnings_items = "".join(_earnings_row_html(r) for _, r in earnings_this_week.iterrows())\r\n        earnings_section_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xf0\x9f\x93\x8a Earnings this week</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{earnings_items}</ul>"\r\n        )\r\n\r\n    upcoming_earnings_html = ""\r\n    if len(upcoming_earnings) > 0:\r\n        upcoming_items = "".join(\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"{r[\'upcoming_earnings_date\'].strftime(\'%A %Y-%m-%d\')}</li>"\r\n            for _, r in upcoming_earnings.iterrows()\r\n        )\r\n        upcoming_earnings_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xf0\x9f\x93\x85 Earnings coming up next week</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{upcoming_items}</ul>"\r\n        )\r\n\r\n    quiet_html = ""\r\n    if len(quiet_positions) > 0:\r\n        quiet_names = ", ".join(quiet_positions["ticker"].tolist())\r\n        quiet_html = (\r\n            f"<p style=\'margin-top:20px; font-size:13px; color:#5B6472;\'>"\r\n            f"\xe2\x9c\x85 No notable changes ({len(quiet_positions)}): {quiet_names}</p>"\r\n        )\r\n\r\n    html_body = f"""\r\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\r\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\r\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Portfolio Watch</div>\r\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">Your positions, checked</div>\r\n        </div>\r\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\r\n            {week_summary_html}\r\n            <h4 style="color:#101825; font-size:15px; margin:0 0 4px 0;">\xf0\x9f\x94\x84 Trend changes this week</h4>\r\n            {flips_html}\r\n            {earnings_section_html}\r\n            {upcoming_earnings_html}\r\n            {quiet_html}\r\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\r\n                See the full picture under\r\n                <a href="https://hestys.streamlit.app/?view=analyze&subview=portfolio" style="color:#1FAE96; font-weight:600; text-decoration:none;">Analyze &gt; Portfolio Overview</a> on the site.\r\n            </p>\r\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\r\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\r\n        </div>\r\n    </div>\r\n    """\r\n    return text_body, html_body\r\n\r\n\r\ndef main() -> None:\r\n    portfolio_holdings = get_current_holdings()\r\n    print(f"Portfolio Watch: {len(portfolio_holdings)} posities checken "\r\n          f"(weekly, ATR-periode {ATR_LENGTH}, multiplier {ATR_MULTIPLIER})...\\n")\r\n\r\n    results = []\r\n    for holding in portfolio_holdings:\r\n        result = check_holding(holding["naam"], holding["ticker"])\r\n        if result:\r\n            result["shares"] = holding.get("shares")\r\n            results.append(result)\r\n            marker = " <-- LET OP, recent gewijzigd" if result["recent_gewijzigd"] else ""\r\n            if result["sinds"] is not None:\r\n                print(f"  {result[\'naam\']}: {result[\'status\']} sinds {result[\'sinds\']} "\r\n                      f"({result[\'weken_in_trend\']} weken){marker}")\r\n            else:\r\n                print(f"  {result[\'naam\']}: {result[\'status\']}")\r\n\r\n    if not results:\r\n        print("\\nGeen enkele positie kon gecheckt worden -- controleer je tickers.")\r\n        return\r\n\r\n    df = pd.DataFrame(results)\r\n    df.to_csv("portfolio_watch.csv", index=False)\r\n\r\n    print(f"\\n=== OVERZICHT ===\\n")\r\n    print(df.to_string(index=False))\r\n\r\n    print("\\nOpgeslagen in \'portfolio_watch.csv\'.")\r\n\r\n    if email_is_configured():\r\n        text_body, html_body = build_email_body(df)\r\n        n_changed = int(df["recent_gewijzigd"].sum())\r\n        n_earnings = int((df["earnings_surprise_pct"].notna()).sum())\r\n        subject_parts = []\r\n        if n_changed > 0:\r\n            subject_parts.append(f"{n_changed} trend change(s)")\r\n        if n_earnings > 0:\r\n            subject_parts.append(f"{n_earnings} earnings update(s)")\r\n        subject = f"Portfolio Watch: {\', \'.join(subject_parts)}" if subject_parts else "Portfolio Watch: no notable changes this week"\r\n        send_email(subject=subject, body_text=text_body, body_html=html_body)\r\n    else:\r\n        print("\\n(E-mail niet verstuurd: nog niet ingesteld in .env.)")\r\n\r\n\r\nif __name__ == "__main__":\r\n    main()\r\n'

WEEKLY_BATCH_CONTENT = b'"""\nWekelijks batch-script: draait de gedeelde screener EN stuurt elke\ngeregistreerde gebruiker een persoonlijke e-mail over hun eigen portfolio.\n\nBedoeld om te draaien via GitHub Actions (dus GEEN Streamlit-context --\nleest configuratie via omgevingsvariabelen, niet via st.secrets zoals\nhet dashboard zelf doet).\n\nBenodigde omgevingsvariabelen (als GitHub Actions secrets, of lokaal in .env):\n  SUPABASE_URL, SUPABASE_ANON_KEY\n  EMAIL_SMTP_SERVER, EMAIL_SMTP_PORT, EMAIL_ADDRESS, EMAIL_APP_PASSWORD\n\nGebruik: python weekly_batch.py\n"""\nfrom __future__ import annotations\n\nimport os\n\nimport pandas as pd\nfrom dotenv import load_dotenv\nfrom supabase import create_client\n\nload_dotenv()\n\nimport screener\nfrom portfolio_watch import check_holding, build_email_body\nfrom emailer import send_email\n\n\ndef get_supabase_client():\n    url = os.environ["SUPABASE_URL"]\n    key = os.environ["SUPABASE_ANON_KEY"]\n    return create_client(url, key)\n\n\ndef get_real_email(email_hash: str) -> str:\n    """\n    Zoekt het echte, verstuurbare e-mailadres op bij een hash -- nodig\n    omdat portfolio_holdings/user_preferences alleen de hash kennen, niet\n    het leesbare adres zelf (zie database.py\'s module-docstring).\n    """\n    client = get_supabase_client()\n    response = client.table("user_identity").select("email").eq("email_hash", email_hash).execute()\n    if response.data:\n        return response.data[0]["email"]\n    return None\n\n\ndef get_all_users_with_holdings() -> dict:\n    """\n    Geeft alle gebruikers en hun ACTIEVE, EIGEN posities terug, gegroepeerd\n    per (gehasht) e-mailadres. Filtert expliciet op is_watchlist=false EN\n    shares > 0 -- zonder deze filters kwamen watchlist-items en al-\n    verkochte posities (shares=0, blijven soms als rij staan i.p.v.\n    verwijderd) ook mee in de Portfolio Watch-mail, wat precies de bron\n    was van \'ik krijg info over posities die ik al verkocht heb\'.\n    """\n    client = get_supabase_client()\n    response = (\n        client.table("portfolio_holdings")\n        .select("*")\n        .eq("is_watchlist", False)\n        .gt("shares", 0)\n        .execute()\n    )\n\n    grouped: dict[str, list[dict]] = {}\n    for row in response.data:\n        grouped.setdefault(row["user_email"], []).append(row)\n    return grouped\n\n\ndef get_all_preferences() -> dict:\n    """Geeft de e-mail-voorkeuren van ALLE gebruikers terug (sleutel = gehasht e-mailadres)."""\n    client = get_supabase_client()\n    response = client.table("user_preferences").select("*").execute()\n    return {row["user_email"]: row for row in response.data}\n\n\ndef run_screener_shared() -> None:\n    """\n    Draait de gedeelde screener 1x -- de resultaten (CSV\'s, incl. Snowball\n    Signal en Rocket List) zijn voor iedereen zichtbaar op de website.\n    send_own_email=False, want de vaste mail naar het eigen GitHub-\n    secrets-adres zou dubbel op kunnen tellen met de per-gebruiker-opt-in-\n    mail hieronder (run_weekly_signals_emails) als dat hetzelfde adres is.\n    """\n    print("=== Gedeelde screener draaien (publiek, voor iedereen zichtbaar) ===")\n    screener.main(send_own_email=False)\n\n\ndef _format_momentocrats_row(row) -> str:\n    return (f"[score {row[\'score\']}] {row[\'ticker\']}: flipped {row[\'weken_geleden\']} week(en) ago "\n            f"({row[\'sinds_omslag_pct\']:+.2f}% since)")\n\n\ndef _format_snowball_row(row) -> str:\n    return (f"{row[\'ticker\']}: ROIC {row[\'roic_pct\']:.1f}%, "\n            f"{row[\'afwijking_fair_value_pct\']:+.1f}% vs. fair value")\n\n\ndef _format_rocket_row(row) -> str:\n    return (f"{row[\'ticker\']}: {row[\'groei_pct\']:.1f}% growth, "\n            f"{row[\'relatieve_sterkte\']:+.1f}% relative strength")\n\n\nSIGNAL_TYPES = {\n    "momentocrats": {\n        "pref_key": "wants_momentocrats_email", "csv": "supertrend_signals.csv",\n        "title": "Momentocrats", "emoji": "\xf0\x9f\x93\xa1", "sort_by": "score", "sort_asc": False,\n        "formatter": _format_momentocrats_row,\n    },\n    "snowball": {\n        "pref_key": "wants_snowball_email", "csv": "snowball_signals.csv",\n        "title": "Snowballers", "emoji": "\xf0\x9f\x90\xa6", "sort_by": "afwijking_fair_value_pct", "sort_asc": True,\n        "formatter": _format_snowball_row,\n    },\n    "rocket": {\n        "pref_key": "wants_rocket_email", "csv": "rocket_list_signals.csv",\n        "title": "Rocket List", "emoji": "\xf0\x9f\x9a\x80", "sort_by": "groei_pct", "sort_asc": False,\n        "formatter": _format_rocket_row,\n    },\n}\n\n\ndef build_weekly_signals_email(sections: list, is_premium: bool = False, daily_flips_text: str = "", daily_flips_html: str = "") -> tuple:\n    """\n    Bouwt 1 gecombineerde mail voor alle signaal-types die deze gebruiker\n    heeft aangevinkt, plus (optioneel) vrijdag\'s dagelijkse flips.\n\n    Toont altijd top 3 per signaal, OOK voor premium -- een mail met\n    tientallen regels per signaal is geen prettige samenvatting meer,\n    dat is precies waar Discover (met een scrollbare tabel) voor is.\n    De \'is_premium\'-parameter blijft bestaan voor later (zodra premium\n    functioneel is), maar be\xc3\xafnvloedt de mail-inhoud nu bewust niet.\n\n    sections: lijst van dicts met keys \'title\', \'emoji\', \'df\', \'formatter\'.\n    daily_flips_text/daily_flips_html: optioneel, van build_daily_flips_section() --\n    leeg als er niks te melden was (dan wordt deze sectie gewoon overgeslagen).\n    """\n    display_limit = 3\n    text_lines = ["Good morning from Hesty\'s -- your weekly signals are in.", ""]\n    html_sections_list = []\n\n    for section in sections:\n        total_this_section = len(section["df"])\n        top_n = section["df"].head(display_limit)\n        text_lines.append(f"{section[\'emoji\']} {section[\'title\']} (top {len(top_n)} of {total_this_section} total):")\n        for _, row in top_n.iterrows():\n            text_lines.append(f"  - {section[\'formatter\'](row)}")\n        text_lines.append("")\n\n        rows_html = "".join(\n            f"<li style=\'padding:4px 0;color:#101825;\'>{section[\'formatter\'](row)}</li>"\n            for _, row in top_n.iterrows()\n        )\n        html_sections_list.append(f"""\n        <h4 style="color:#101825; font-size:16px; margin:20px 0 8px 0;">{section[\'emoji\']} {section[\'title\']}</h4>\n        <ul style="margin:0; padding-left:20px; font-size:14px;">{rows_html}</ul>\n        """)\n\n    if daily_flips_text:\n        text_lines.append(daily_flips_text)\n    if daily_flips_html:\n        html_sections_list.append(daily_flips_html)\n\n    text_lines += [\n        "See the full lists, sector rotation, and top movers under Discover on the site.",\n        "",\n        "-- Hesty\'s, your personal investment assistant",\n        "",\n        "This is a screener, not investment advice.",\n    ]\n    text_body = "\\n".join(text_lines)\n\n    html_body = f"""\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Weekly</div>\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">Your weekly signals are in</div>\n        </div>\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\n            {\'\'.join(html_sections_list)}\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\n                See the full lists, sector rotation, and top movers under\n                <a href="https://hestys.streamlit.app/?view=discover" style="color:#1FAE96; font-weight:600; text-decoration:none;">Discover</a> on the site.\n            </p>\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\n        </div>\n    </div>\n    """\n    return text_body, html_body\n\n\ndef run_weekly_signals_emails(preferences: dict, daily_flips_text: str = "", daily_flips_html: str = "") -> None:\n    """\n    Stuurt 1 gecombineerde mail per gebruiker, met alleen de signaal-types\n    waar diegene zich voor heeft aangemeld (top 3 gratis / top 10 premium),\n    plus (optioneel) vrijdag\'s dagelijkse flips erbij.\n\n    daily_flips_text/daily_flips_html: alleen toegevoegd aan mails die\n    sowieso al verstuurd worden (dus gebruikers met minstens 1 signaal-\n    type aangevinkt) -- geen nieuwe categorie gebruikers die anders\n    niks zouden ontvangen.\n    """\n    print("\\n=== Wekelijkse signalen-mails versturen aan opt-in-gebruikers ===")\n\n    # Laad elke CSV maar 1x, niet per gebruiker opnieuw\n    csv_cache = {}\n    for key, config in SIGNAL_TYPES.items():\n        if os.path.exists(config["csv"]):\n            df = pd.read_csv(config["csv"])\n            if not df.empty:\n                df = df.sort_values(config["sort_by"], ascending=config["sort_asc"])\n                csv_cache[key] = df\n\n    for user_email_hash, prefs in preferences.items():\n        sections = []\n        for key, config in SIGNAL_TYPES.items():\n            if not prefs.get(config["pref_key"]):\n                continue\n            if key not in csv_cache:\n                continue\n            sections.append({\n                "title": config["title"], "emoji": config["emoji"],\n                "df": csv_cache[key], "formatter": config["formatter"],\n            })\n\n        if not sections:\n            continue\n\n        real_email = get_real_email(user_email_hash)\n        if not real_email:\n            print(f"  Kon geen e-mailadres vinden voor hash {user_email_hash[:12]}... -- overgeslagen.")\n            continue\n\n        is_premium = bool(prefs.get("is_premium", False))\n        print(f"  {real_email} ({\'premium\' if is_premium else \'free\'}): {\', \'.join(s[\'title\'] for s in sections)}")\n        text_body, html_body = build_weekly_signals_email(\n            sections, is_premium=is_premium,\n            daily_flips_text=daily_flips_text, daily_flips_html=daily_flips_html,\n        )\n        total_signals = sum(len(s["df"]) for s in sections)\n        subject = f"Hesty\'s Weekly: {total_signals} new signal(s) this week"\n        send_email(subject=subject, body_text=text_body, body_html=html_body, to_email=real_email)\n\n\ndef run_portfolio_emails(preferences: dict) -> None:\n    """\n    Checkt en mailt elke geregistreerde gebruiker zijn eigen, persoonlijke\n    portfolio -- behalve als hij dat expliciet heeft uitgezet. Standaard AAN\n    (ook voor gebruikers die nog nooit hun voorkeuren hebben aangepast).\n    """\n    print("\\n=== Persoonlijke portfolio-e-mails versturen ===")\n    users = get_all_users_with_holdings()\n    print(f"{len(users)} gebruiker(s) gevonden met een portfolio.")\n\n    for user_email_hash, holdings in users.items():\n        user_prefs = preferences.get(user_email_hash, {})\n        if not user_prefs.get("wants_portfolio_email", True):\n            print(f"\\n--- {user_email_hash[:12]}...: heeft de portfolio-mail uitgezet, overgeslagen ---")\n            continue\n\n        real_email = get_real_email(user_email_hash)\n        if not real_email:\n            print(f"\\n--- {user_email_hash[:12]}...: geen e-mailadres gevonden, overgeslagen ---")\n            continue\n\n        print(f"\\n--- {real_email} ({len(holdings)} positie(s)) ---")\n        results = []\n        for holding in holdings:\n            result = check_holding(holding["naam"], holding["ticker"])\n            if result:\n                result["shares"] = holding.get("shares")\n                results.append(result)\n\n        if not results:\n            print("  Geen van de posities kon gecheckt worden -- geen mail verstuurd.")\n            continue\n\n        df = pd.DataFrame(results)\n        text_body, html_body = build_email_body(df)\n        n_changed = int(df["recent_gewijzigd"].sum())\n        n_earnings = int((df["earnings_surprise_pct"].notna()).sum())\n        subject_parts = []\n        if n_changed > 0:\n            subject_parts.append(f"{n_changed} trend change(s)")\n        if n_earnings > 0:\n            subject_parts.append(f"{n_earnings} earnings update(s)")\n        subject = f"Portfolio Watch: {\', \'.join(subject_parts)}" if subject_parts else "Portfolio Watch: no notable changes this week"\n\n        send_email(subject=subject, body_text=text_body, body_html=html_body, to_email=real_email)\n\n\ndef run_daily_flip_scan_for_weekly() -> None:\n    """\n    Draait de dagelijkse flip-scan OPNIEUW, specifiek voor de zaterdag-\n    weekly-mail -- dit vangt de VOLLEDIGE, net-afgeronde vrijdag-sessie op.\n    (De reguliere vrijdagochtend-scan draaide namelijk vroeg, VOORDAT de\n    Amerikaanse beurs zelfs maar open was, en liet dus donderdag-vs-\n    woensdag\'s beweging zien, niet de volledige vrijdag-sessie.)\n\n    Schrijft dezelfde bestanden als de dagelijkse scan (supertrend_signals_daily.csv,\n    top_movers.csv) -- verstuurt zelf GEEN aparte mail, de resultaten worden\n    hieronder in de weekly-mail verwerkt.\n    """\n    import screener_daily\n    print("\\n=== Dagelijkse flip-scan opnieuw draaien (voor de volledige vrijdag-sessie) ===")\n    screener_daily.main(send_own_email=False)\n\n\ndef build_daily_flips_section() -> tuple:\n    """\n    Bouwt een tekst- en HTML-fragment met de belangrijkste flips uit de\n    zojuist opnieuw gedraaide dagelijkse scan (dus: vrijdag\'s volledige\n    sessie) -- toegevoegd aan de zaterdag-weekly-mail, i.p.v. hiervoor een\n    aparte mail te sturen. Geeft (leeg, leeg) terug als er geen data is\n    of geen signalen waren, zodat de aanroeper deze sectie dan gewoon\n    kan overslaan.\n    """\n    if not os.path.exists("supertrend_signals_daily.csv"):\n        return "", ""\n    df_daily = pd.read_csv("supertrend_signals_daily.csv")\n    if df_daily.empty:\n        return "", ""\n\n    df_daily = df_daily.sort_values("score", ascending=False)\n    display_limit = 5\n    top_n = df_daily.head(display_limit)\n\n    text_lines = [f"\xf0\x9f\x93\x85 Friday\'s daily flips (top {len(top_n)} of {len(df_daily)} total):"]\n    for _, row in top_n.iterrows():\n        text_lines.append(\n            f"  - [{row[\'score\']}] {row[\'ticker\']}: {row[\'prijs_bij_omslag\']} -> {row[\'prijs_nu\']} "\n            f"({row[\'sinds_omslag_pct\']:+.2f}%)"\n        )\n    text_lines.append("")\n    text_fragment = "\\n".join(text_lines)\n\n    rows_html = "".join(\n        f"<li style=\'padding:4px 0;color:#101825;\'>[{row[\'score\']}] {row[\'ticker\']}: "\n        f"{row[\'prijs_bij_omslag\']} &rarr; {row[\'prijs_nu\']} ({row[\'sinds_omslag_pct\']:+.2f}%)</li>"\n        for _, row in top_n.iterrows()\n    )\n    html_fragment = f"""\n    <h4 style="color:#101825; font-size:16px; margin:20px 0 8px 0;">\xf0\x9f\x93\x85 Friday\'s daily flips (top {len(top_n)} of {len(df_daily)} total)</h4>\n    <ul style="margin:0; padding-left:20px; font-size:14px;">{rows_html}</ul>\n    """\n    return text_fragment, html_fragment\n\n\ndef run_saturday() -> None:\n    """\n    Zaterdag: de gedeelde screener + wekelijkse signalen-mails (Momentocrats/\n    Snowballers/Rocket List) -- nu AANGEVULD met vrijdag\'s volledige\n    dagelijkse flips (i.p.v. daarvoor een aparte mail te sturen). Portfolio\n    Watch is BEWUST verplaatst naar zondag (zie run_sunday) -- anders kreeg\n    je 2-3 mails tegelijk op zaterdagochtend.\n    """\n    run_screener_shared()\n    run_daily_flip_scan_for_weekly()\n    all_preferences = get_all_preferences()\n    daily_flips_text, daily_flips_html = build_daily_flips_section()\n    run_weekly_signals_emails(all_preferences, daily_flips_text=daily_flips_text, daily_flips_html=daily_flips_html)\n\n\ndef run_sunday() -> None:\n    """Zondag: alleen Portfolio Watch -- apart van de zaterdag-signalen, geen mail-opeenstapeling meer."""\n    all_preferences = get_all_preferences()\n    run_portfolio_emails(all_preferences)\n\n\nif __name__ == "__main__":\n    import sys\n    mode = sys.argv[1] if len(sys.argv) > 1 else "saturday"\n    if mode == "saturday":\n        run_saturday()\n    elif mode == "sunday":\n        run_sunday()\n    else:\n        raise ValueError(f"Onbekende modus: \'{mode}\' -- gebruik \'saturday\' of \'sunday\'.")\n    print("\\nKlaar.")\n'

with open("portfolio_watch.py", "wb") as f:
    f.write(PORTFOLIO_WATCH_CONTENT)
with open("weekly_batch.py", "wb") as f:
    f.write(WEEKLY_BATCH_CONTENT)
print(f"Weggeschreven: portfolio_watch.py ({len(PORTFOLIO_WATCH_CONTENT)} bytes), weekly_batch.py ({len(WEEKLY_BATCH_CONTENT)} bytes)")
print("git add .")
print('git commit -m "Portfolio Watch: add weekly return, best/worst, and upcoming earnings sections"')
print("git push")
